			x--;
			sb.insert(0, (char) ('a' + x % 26));
		}
		return sb.toString();
	}

	/** Unique, letters-only surname (starts with "Sur"). */
	protected String uniqueLastName() {
		return "Sur" + letters(seq());
	}

	/** Unique, letters-only given name (starts with "Fn"). Use this instead of names like
