61	 */
62	
63	@RestController
64	@CrossOrigin(exposedHeaders = "errors, content-type")
65	@RequestMapping("/api")
66	public class OwnerRestControllerV1 implements OwnersApi {
67	
68	    /** Dedicated audit logger for owner lifecycle side-effects. */
69	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
70	
71	    /**
72	     * Pragmatic check for a syntactically valid email address: a non-empty local
73	     * part, a single '@', and a domain with at least one dot-separated label.
74	     */
75	    private static final Pattern EMAIL_PATTERN =
76	        Pattern.compile("^[A-Za-z0-9._%+-]+@[A-Za-z0-9-]+(\\.[A-Za-z0-9-]+)+$");
77	
78	    /**
79	     * Disposable email domains that are rejected: an owner email whose domain is one of
80	     * these is treated as invalid so the create/update is rejected with 400. Compared
81	     * case-insensitively against the normalized (lower-cased) email domain.
82	     */
83	    private static final java.util.Set<String> DISPOSABLE_EMAIL_DOMAINS =
84	        java.util.Set.of("mailinator.com", "tempmail.com", "guerrillamail.com");
85	
86	    /**
87	     * Common street-type abbreviations expanded during address normalization,
88	     * keyed by their upper-cased form.
89	     */
90	    private static final Map<String, String> ADDRESS_ABBREVIATIONS =
91	        Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
92	
93	    /**
94	     * Required national-number length keyed by E.164 country calling code: a
95	     * {@code '+61'} (Australia) number carries 9 national digits and a {@code '+1'}
96	     * (NANP) number carries 10. A number whose country code is listed here must have
97	     * exactly the mandated number of national digits.
98	     */
99	    private static final Map<String, Integer> NATIONAL_NUMBER_LENGTHS =
100	        Map.of("61", 9, "1", 10);
101	
102	    /**
103	     * Inclusive 4-digit postcode range {@code {low, high}} keyed by the region derived
104	     * from the owner's city (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099). A city whose
105	     * region is not listed here (see {@link OwnerMapper#CITY_REGION}) accepts any 4-digit
106	     * postcode.
107	     */
108	    private static final Map<String, int[]> REGION_POSTCODE_RANGES =
109	        Map.of("NSW", new int[] {2000, 2099}, "VIC", new int[] {3000, 3099},
110	            "QLD", new int[] {4000, 4099});
111	
112	    private final ClinicService clinicService;
113	
114	    private final OwnerMapper ownerMapper;
115	
116	    private final PetMapper petMapper;
117	
118	    private final VisitMapper visitMapper;
119	
120	    public OwnerRestControllerV1(ClinicService clinicService,
121	                                 OwnerMapper ownerMapper,
122	                                 PetMapper petMapper,
123	                                 VisitMapper visitMapper) {
124	        this.clinicService = clinicService;
125	        this.ownerMapper = ownerMapper;
126	        this.petMapper = petMapper;
127	        this.visitMapper = visitMapper;
128	    }
129	
130	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
131	    @Override
132	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
133	        Collection<Owner> owners;
134	        if (lastName != null) {
135	            owners = this.clinicService.findOwnerByLastName(lastName);
136	        } else {
137	            owners = this.clinicService.findAllOwners();
138	        }
139	        if (owners.isEmpty()) {
140	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
141	        }
142	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
143	    }
144	
145	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
146	    @Override
147	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
148	        Owner owner = this.clinicService.findOwnerById(ownerId);
149	        if (owner == null) {
150	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
151	        }
152	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
153	    }
154	
155	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
156	    @Override
157	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
158	        // Validate & normalize the optional email; reject the create when it is present but invalid.
159	        if (!normalizeEmail(ownerFieldsDto)) {
160	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
161	        }
162	        // Validate & normalize the optional postcode; reject the create when it is present but
163	        // not valid for the owner's city (see normalizePostcode).
164	        if (!normalizePostcode(ownerFieldsDto)) {
165	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
166	        }
167	        // Normalize the supplied address — the structured 'addressLine1'/'addressLine2' when
168	        // present, otherwise the flat 'address' — storing the normalized form (and the composed
169	        // 'address') back on the DTO so it is what gets persisted and compared. Reject the create
170	        // when no address is supplied in either form (see normalizeAddresses).
171	        if (!normalizeAddresses(ownerFieldsDto)) {
172	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
173	        }
174	        // Reject the create when the owner's city is already at capacity, i.e. it already
175	        // contains 50 or more owners (compared case-insensitively).
176	        if (countOwnersInCity(ownerFieldsDto.getCity()) >= 50) {
177	            return new ResponseEntity<>(HttpStatus.CONFLICT);
178	        }
179	        // Normalize the telephone to E.164; reject the create when it cannot form a valid number.
180	        String normalizedTelephone = toE164(ownerFieldsDto.getTelephone());
181	        if (normalizedTelephone == null) {
182	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
183	        }
184	        ownerFieldsDto.setTelephone(normalizedTelephone);
185	        // Consolidated duplicate detection. All former separate telephone, email and household
186	        // duplicate checks are now expressed through the single derived identity key
187	        // '<normalizedTelephone>|<email or empty>|<householdId>' (see OwnerMapper#identityKey).
188	        // A create is rejected only when the new owner's identity collides with an existing owner's.
189	        // Because the telephone is part of the identity, two members of the same household with
190	        // different telephones no longer collide and are both allowed; only owners that share the
191	        // same normalized telephone and email are treated as the same identity.
192	        Owner candidate = ownerMapper.toOwner(ownerFieldsDto);
193	        String contactIdentity = identityContact(candidate);
194	        boolean identityInUse = this.clinicService.findAllOwners().stream()
195	            .filter(existing -> !existing.isDeleted())
196	            .anyMatch(existing -> contactIdentity.equals(identityContact(existing)));
197	        if (identityInUse) {
198	            return new ResponseEntity<>(HttpStatus.CONFLICT);
199	        }
200	        // Household duplicate detection keyed on the deterministic householdId, derived from the
201	        // normalized last name and postcode (see OwnerMapper#householdId). Owners sharing a last
202	        // name and postcode share the same household. A second owner in an existing household is
203	        // rejected as a household duplicate (409) unless the request declares 'sharesHousehold',
204	        // in which case it is created as a declared household member — 'sharesHousehold' only
205	        // bypasses this block; the household link itself now follows from the computed householdId.
206	        String householdId = ownerMapper.householdId(candidate);
207	        boolean householdExists = this.clinicService.findAllOwners().stream()
208	            .filter(existing -> !existing.isDeleted())
209	            .anyMatch(existing -> householdId.equals(ownerMapper.householdId(existing)));
210	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
211	        if (householdExists && !sharesHousehold) {
212	            return new ResponseEntity<>(HttpStatus.CONFLICT);
213	        }
214	        boolean declaredMember = householdExists && sharesHousehold;
215	        // Determine the effective registration date — the value supplied on the request, or the
216	        // server's current date when none was supplied — and roll it forward to the next business
217	        // day: a Saturday or Sunday moves to the following Monday. Everything derived from the
218	        // registration date (membership-number year segment, per-day create-limit) uses this
219	        // adjusted date.
220	        LocalDate registrationDate = ownerFieldsDto.getRegistrationDate();
221	        if (registrationDate == null) {
222	            registrationDate = LocalDate.now();
223	        }
224	        // Reject a supplied registration date that lies in the future (later than the
225	        // server's current date): an owner cannot be registered ahead of time.
226	        else if (registrationDate.isAfter(LocalDate.now())) {
227	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
228	        }
229	        registrationDate = toBusinessDay(registrationDate);
230	        // Reject the create when the daily sign-up limit has been reached, i.e. 100 or more
231	        // owners have already been registered on this (adjusted) business day.
232	        if (countOwnersRegisteredOn(registrationDate) >= 100) {
233	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
234	        }
235	        HttpHeaders headers = new HttpHeaders();
236	        Owner owner = candidate;
237	        owner.setRegistrationDate(registrationDate);
238	        // Assign the customer code as '<REGION>-<HASH8>': the region derived from the owner's
239	        // postcode (falling back to the city, then 'UNKNOWN') and the first 8 upper-case hex
240	        // characters of the SHA-256 of the normalized telephone concatenated with the last name.
241	        owner.setCustomerCode(customerCode(owner));
242	        // Record how many existing owners already share this owner's first and last name
243	        // (compared case-insensitively) at the moment before this owner is created.
244	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
245	        // Flag a bulk sign-up when more than 80 owners have already been created today, i.e.
246	        // registered on this (adjusted) business day before this owner is created.
247	        owner.setBulkSignupWarning(countOwnersRegisteredOn(registrationDate) > 80);
248	        // Record the size of this owner's household after this create: the number of existing
249	        // owners sharing the same household (i.e. the same computed householdId) plus this owner.
250	        owner.setHouseholdSize(countHouseholdMembers(owner) + 1);
251	        // Flag a possible (soft) duplicate: this owner is not a hard identity duplicate, but it
252	        // shares an existing owner's last name (case-insensitively) and postcode while carrying a
253	        // different telephone. When such a match exists, record it as 'possibleDuplicate' with
254	        // 'possibleDuplicateOf' set to the matching owner's id; otherwise it is not a possible
255	        // duplicate. A declared household member is an acknowledged member, not a suspected
256	        // duplicate, so it is never flagged.
257	        if (declaredMember) {
258	            owner.setPossibleDuplicate(false);
259	            owner.setPossibleDuplicateOf(null);
260	        }
261	        else {
262	            Owner softMatch = findPossibleDuplicate(owner);
263	            owner.setPossibleDuplicate(softMatch != null);
264	            owner.setPossibleDuplicateOf(softMatch == null ? null : softMatch.getId());
265	        }
266	        this.clinicService.saveOwner(owner);
267	        // Emit an audit line recording the new owner's id, customer code, registration date,
268	        // membership level and membership number.
269	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
270	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
271	            ownerMapper.membershipLevel(owner), ownerMapper.membershipNumber(owner));
272	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
273	        headers.setLocation(UriComponentsBuilder.newInstance()
274	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
275	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
276	    }
277	
278	    /**
279	     * Validate and normalize the optional owner email in place.
280	     *
281	     * <p>An absent (or blank) email is allowed and is normalized to {@code null}.
282	     * When present it must be a syntactically valid address; a valid address is
283	     * stored back on the DTO lower-cased. Returns {@code false} when an email is
284	     * present but syntactically invalid, so the caller can reject with 400.
285	     */
286	    private boolean normalizeEmail(OwnerFieldsDto ownerFieldsDto) {
287	        String email = ownerFieldsDto.getEmail();
288	        if (email == null || email.isBlank()) {
289	            ownerFieldsDto.setEmail(null);
290	            return true;
291	        }
292	        String normalized = email.trim().toLowerCase(Locale.ROOT);
293	        if (!EMAIL_PATTERN.matcher(normalized).matches()) {
294	            return false;
295	        }
296	        // Reject addresses whose domain is on the disposable-domain blocklist.
297	        String domain = normalized.substring(normalized.indexOf('@') + 1);
298	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
299	            return false;
300	        }
301	        ownerFieldsDto.setEmail(normalized);
302	        return true;
303	    }
304	
305	    /**
306	     * Validate the optional owner postcode in place.
307	     *
308	     * <p>An absent (or blank) postcode is allowed and is normalized to {@code null}.
309	     * When present it must be exactly 4 digits, and — when the owner's city maps to a
310	     * known region via {@link OwnerMapper#CITY_REGION} — it must fall within that
311	     * region's inclusive postcode range (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099).
312	     * A city with no known region accepts any 4-digit postcode. Returns {@code false}
313	     * when a postcode is present but malformed or out of range, so the caller can
314	     * reject with 400.
315	     */
316	    private boolean normalizePostcode(OwnerFieldsDto ownerFieldsDto) {
317	        String postcode = ownerFieldsDto.getPostcode();
318	        if (postcode == null || postcode.isBlank()) {
319	            ownerFieldsDto.setPostcode(null);
320	            return true;
321	        }
322	        if (!postcode.matches("\\d{4}")) {
323	            return false;
324	        }
325	        String region = OwnerMapper.CITY_REGION.get(ownerFieldsDto.getCity());
326	        int[] range = region == null ? null : REGION_POSTCODE_RANGES.get(region);
327	        if (range != null) {
328	            int value = Integer.parseInt(postcode);
329	            if (value < range[0] || value > range[1]) {
330	                return false;
331	            }
332	        }
333	        return true;
334	    }
335	
336	    /**
337	     * Validate and normalize the owner's address fields in place, preferring the structured
338	     * form over the flat 'address' for backward compatibility.
339	     *
340	     * <p>When a non-blank {@code addressLine1} is supplied it is the structured form: both
341	     * {@code addressLine1} and (when present) {@code addressLine2} are normalized and stored
342	     * back, and {@code address} is set to the composed value — the normalized addressLine1,
343	     * with a single space and the normalized addressLine2 appended when addressLine2 is present.
344	     * Otherwise the flat {@code address} is normalized in place and the structured lines are
345	     * cleared. Returns {@code false} when no address is supplied in either form (both the
346	     * structured addressLine1 and the flat address are blank once normalized), so the caller
347	     * can reject with 400.
348	     */
349	    private boolean normalizeAddresses(OwnerFieldsDto ownerFieldsDto) {
350	        String rawLine1 = ownerFieldsDto.getAddressLine1();
351	        if (rawLine1 != null && !rawLine1.isBlank()) {
352	            String line1 = normalizeAddress(rawLine1);
353	            if (line1.isBlank()) {
354	                return false;
355	            }
356	            ownerFieldsDto.setAddressLine1(line1);
357	            String rawLine2 = ownerFieldsDto.getAddressLine2();
358	            String composed = line1;
359	            if (rawLine2 != null && !rawLine2.isBlank()) {
360	                String line2 = normalizeAddress(rawLine2);
361	                ownerFieldsDto.setAddressLine2(line2);
362	                composed = line1 + " " + line2;
363	            }
364	            else {
365	                ownerFieldsDto.setAddressLine2(null);
366	            }
367	            ownerFieldsDto.setAddress(composed);
368	            return true;
369	        }
370	        // No structured address: fall back to the flat 'address' input.
371	        String canonicalAddress = normalizeAddress(ownerFieldsDto.getAddress());
372	        if (canonicalAddress.isBlank()) {
373	            return false;
374	        }
375	        ownerFieldsDto.setAddress(canonicalAddress);
376	        ownerFieldsDto.setAddressLine1(null);
377	        ownerFieldsDto.setAddressLine2(null);
378	        return true;
379	    }
380	
381	    /**
382	     * Normalize an owner address: trim, collapse each run of whitespace to a single
383	     * space, upper-case, and expand common street-type abbreviations
384	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}).
385	     * A {@code null} value normalizes to the empty string.
386	     */
387	    private static String normalizeAddress(String value) {
388	        if (value == null) {
389	            return "";
390	        }
391	        String collapsed = value.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
392	        if (collapsed.isEmpty()) {
393	            return "";
394	        }
395	        String[] tokens = collapsed.split(" ");
396	        StringBuilder sb = new StringBuilder(collapsed.length());
397	        for (int i = 0; i < tokens.length; i++) {
398	            if (i > 0) {
399	                sb.append(' ');
400	            }
401	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
402	        }
403	        return sb.toString();
404	    }
405	
406	    /**
407	     * The contact portion of an owner's derived identity key: its normalized telephone and
408	     * email ('&lt;normalizedTelephone&gt;|&lt;email or empty&gt;'), i.e. the identity key
409	     * without the household segment. Two owners share an identity when this value is equal;
410	     * because the telephone is part of it, members of one household with different telephones
411	     * do not collide. A {@code null} email contributes the empty string.
412	     */
413	    private static String identityContact(Owner owner) {
414	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
415	        String email = owner.getEmail() == null ? "" : owner.getEmail();
416	        return telephone + "|" + email;
417	    }
418	
419	    /**
420	     * Normalize a telephone number to E.164 form.
421	     *
422	     * <p>Spaces, dashes and brackets are stripped. When the number carries an
423	     * explicit leading {@code '+'} and country code it is kept; otherwise the
424	     * country code {@code '+61'} is assumed and a single leading {@code '0'} is
425	     * dropped from the national digits. The result must contain 8 to 15 digits
426	     * after the {@code '+'}, and — for a recognised country calling code — exactly
427	     * the national-number length that code mandates ({@code '+61'} => 9 national
428	     * digits, {@code '+1'} => 10).
429	     *
430	     * @return the E.164 string (e.g. {@code +61412345678}), or {@code null} when
431	     *         the input is absent or cannot form a valid E.164 number.
432	     */
433	    private static String toE164(String raw) {
434	        if (raw == null) {
435	            return null;
436	        }
437	        String trimmed = raw.trim();
438	        boolean hasCountryCode = trimmed.startsWith("+");
439	        // Strip spaces, dashes and brackets.
440	        String stripped = trimmed.replaceAll("[\\s()\\-]", "");
441	        String digits;
442	        if (hasCountryCode) {
443	            // Keep the explicit country code; drop the leading '+' for validation.
444	            digits = stripped.substring(1);
445	        } else {
446	            // No country code: assume '+61' and drop a single leading '0'.
447	            String national = stripped.startsWith("0") ? stripped.substring(1) : stripped;
448	            digits = "61" + national;
449	        }
450	        if (!digits.matches("\\d{8,15}")) {
451	            return null;
452	        }
453	        // For a recognised country calling code, enforce the exact national-number length it
454	        // mandates (e.g. '+61' => 9 national digits, '+1' => 10). Longer codes win so a '+61'
455	        // number is not mistaken for a '+6...' one. Unknown codes keep the generic 8-15 rule.
456	        for (String countryCode : NATIONAL_NUMBER_LENGTHS.keySet().stream()
457	                .sorted((a, b) -> b.length() - a.length()).toList()) {
458	            if (digits.startsWith(countryCode)) {
459	                int nationalLength = digits.length() - countryCode.length();
460	                if (nationalLength != NATIONAL_NUMBER_LENGTHS.get(countryCode)) {
461	                    return null;
462	                }
463	                break;
464	            }
465	        }
466	        return "+" + digits;
467	    }
468	
469	    /**
470	     * Count the existing owners whose first and last name match the given names,
471	     * compared case-insensitively. Used to record an owner's namesake count at the
472	     * moment before it is created.
473	     */
474	    private int countNamesakes(String firstName, String lastName) {
475	        return (int) this.clinicService.findAllOwners().stream()
476	            .filter(existing -> existing.getFirstName() != null
477	                && existing.getFirstName().equalsIgnoreCase(firstName)
478	                && existing.getLastName() != null
479	                && existing.getLastName().equalsIgnoreCase(lastName))
480	            .count();
481	    }
482	
483	    /**
484	     * Count the existing owners in the same household as the given owner, i.e. those sharing its
485	     * computed householdId (derived from the normalized last name and postcode). Used, together
486	     * with the owner being created, to derive the household size recorded on the owner.
487	     */
488	    private int countHouseholdMembers(Owner owner) {
489	        String householdId = ownerMapper.householdId(owner);
490	        return (int) this.clinicService.findAllOwners().stream()
491	            .filter(existing -> householdId.equals(ownerMapper.householdId(existing)))
492	            .count();
493	    }
494	
495	    /**
496	     * Find an existing owner that the given (not-yet-created) owner is a possible (soft) duplicate
497	     * of: one sharing the same last name (compared case-insensitively) and the same postcode, but
498	     * carrying a different normalized telephone. Owners without a postcode never match (the postcode
499	     * must be shared). When several existing owners match, the one with the lowest id is returned so
500	     * the result is deterministic. Returns {@code null} when there is no such match.
501	     */
502	    private Owner findPossibleDuplicate(Owner candidate) {
503	        if (candidate.getPostcode() == null) {
504	            return null;
505	        }
506	        return this.clinicService.findAllOwners().stream()
507	            .filter(existing -> !existing.isDeleted())
508	            .filter(existing -> existing.getLastName() != null
509	                && existing.getLastName().equalsIgnoreCase(candidate.getLastName())
510	                && candidate.getPostcode().equals(existing.getPostcode())
511	                && !candidate.getTelephone().equals(existing.getTelephone()))
512	            .min(java.util.Comparator.comparing(Owner::getId))
513	            .orElse(null);
514	    }
515	
516	    /**
517	     * Build the owner's customer code, formatted {@code '<REGION>-<HASH8>'}.
518	     *
519	     * <p>{@code REGION} is the region derived from the owner's postcode (see
520	     * {@link #deriveRegion}). {@code HASH8} is the first 8 upper-case hex characters of the
521	     * SHA-256 of the normalized telephone concatenated with the last name
522	     * (e.g. {@code 'NSW-1A2B3C4D'}).
523	     *
524	     * <p>When the computed code collides with an existing owner's customer code, it is
525	     * de-duplicated by appending {@code '-<n>'} with the smallest {@code n} of 2 or more
526	     * that makes it unique.
527	     */
528	    private String customerCode(Owner owner) {
529	        String region = deriveRegion(owner.getPostcode(), owner.getCity());
530	        String hash8 = sha256HexUpper(owner.getTelephone() + owner.getLastName(), 8);
531	        String base = region + "-" + hash8;
532	        Set<String> existing = this.clinicService.findAllOwners().stream()
533	            .map(Owner::getCustomerCode)
534	            .filter(java.util.Objects::nonNull)
535	            .collect(Collectors.toSet());
536	        if (!existing.contains(base)) {
537	            return base;
538	        }
539	        int n = 2;
540	        while (existing.contains(base + "-" + n)) {
541	            n++;
542	        }
543	        return base + "-" + n;
544	    }
545	
546	    /**
547	     * Derive the owner's region, preferring the postcode. The postcode is matched against
548	     * each region's inclusive range (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099); only when
549	     * it is absent or in no known range does this fall back to the fixed city-to-region table
550	     * (see {@link OwnerMapper#CITY_REGION}), and finally {@code 'UNKNOWN'}.
551	     */
552	    private static String deriveRegion(String postcode, String city) {
553	        if (postcode != null && postcode.matches("\\d{4}")) {
554	            int value = Integer.parseInt(postcode);
555	            for (Map.Entry<String, int[]> entry : REGION_POSTCODE_RANGES.entrySet()) {
556	                int[] range = entry.getValue();
557	                if (value >= range[0] && value <= range[1]) {
558	                    return entry.getKey();
559	                }
560	            }
561	        }
562	        return OwnerMapper.CITY_REGION.getOrDefault(city, "UNKNOWN");
563	    }
564	
565	    /**
566	     * The first {@code length} upper-case hex characters of the SHA-256 digest of the UTF-8
567	     * bytes of {@code value}.
568	     */
569	    private static String sha256HexUpper(String value, int length) {
570	        try {
571	            byte[] digest = MessageDigest.getInstance("SHA-256")
572	                .digest(value.getBytes(StandardCharsets.UTF_8));
573	            StringBuilder sb = new StringBuilder(digest.length * 2);
574	            for (byte b : digest) {
575	                sb.append(String.format("%02X", b));
576	            }
577	            return sb.substring(0, length);
578	        }
579	        catch (NoSuchAlgorithmException e) {
580	            throw new IllegalStateException(e);
581	        }
582	    }
583	
584	    /**
585	     * Count the existing owners located in the given city, compared case-insensitively.
586	     * Used to derive the per-city 4-digit sequence in the customer code.
587	     */
588	    private int countOwnersInCity(String city) {
589	        return (int) this.clinicService.findAllOwners().stream()
590	            .filter(existing -> existing.getCity() != null
591	                && existing.getCity().equalsIgnoreCase(city))
592	            .count();
593	    }
594	
595	    /**
596	     * Count the existing owners whose registration date is the given (adjusted business) date.
597	     * Used to enforce the per-day sign-up limit.
598	     */
599	    private int countOwnersRegisteredOn(LocalDate date) {
600	        return (int) this.clinicService.findAllOwners().stream()
601	            .filter(existing -> date.equals(existing.getRegistrationDate()))
602	            .count();
603	    }
604	
605	    /** Fixed public holidays the business-day roll skips. */
606	    private static final Set<LocalDate> HOLIDAYS = Set.of(
607	        LocalDate.parse("2026-01-01"), LocalDate.parse("2026-01-26"),
608	        LocalDate.parse("2026-04-25"), LocalDate.parse("2026-12-25"),
609	        LocalDate.parse("2026-12-28"));
610	
611	    /**
612	     * Roll a registration date forward onto a business day: a Saturday, Sunday, or listed
613	     * public holiday is moved forward to the next non-holiday weekday; a plain weekday is
614	     * returned unchanged.
615	     */
616	    private static LocalDate toBusinessDay(LocalDate date) {
617	        while (date.getDayOfWeek() == DayOfWeek.SATURDAY
618	            || date.getDayOfWeek() == DayOfWeek.SUNDAY
619	            || HOLIDAYS.contains(date)) {
620	            date = date.plusDays(1);
621	        }
622	        return date;
623	    }
624	
625	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
626	    @Override
627	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
628	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
629	        if (currentOwner == null) {
630	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
631	        }
632	        if (!normalizeEmail(ownerFieldsDto)) {
633	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
634	        }
635	        if (!normalizePostcode(ownerFieldsDto)) {
636	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
637	        }
638	        if (!normalizeAddresses(ownerFieldsDto)) {
639	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
640	        }
641	        String normalizedTelephone = toE164(ownerFieldsDto.getTelephone());
642	        if (normalizedTelephone == null) {
643	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
644	        }
645	        currentOwner.setAddress(ownerFieldsDto.getAddress());
646	        currentOwner.setAddressLine1(ownerFieldsDto.getAddressLine1());
647	        currentOwner.setAddressLine2(ownerFieldsDto.getAddressLine2());
648	        currentOwner.setCity(ownerFieldsDto.getCity());
649	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
650	        currentOwner.setLastName(ownerFieldsDto.getLastName());
651	        currentOwner.setTelephone(normalizedTelephone);
652	        currentOwner.setEmail(ownerFieldsDto.getEmail());
653	        currentOwner.setPostcode(ownerFieldsDto.getPostcode());
654	        this.clinicService.saveOwner(currentOwner);
655	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
656	    }
657	
658	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
659	    @Transactional
660	    @Override
661	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
662	        Owner owner = this.clinicService.findOwnerById(ownerId);
663	        if (owner == null) {
664	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
665	        }
666	        // Soft-delete: flag the owner deleted and retain the record so it can still be
667	        // read back (with 'deleted' true) and is ignored by later duplicate/identity checks.
668	        owner.setDeleted(true);
669	        this.clinicService.saveOwner(owner);
670	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
671	    }
672	
673	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
674	    @Override
675	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
676	        Owner owner = this.clinicService.findOwnerById(ownerId);
677	        if (owner == null) {
678	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
679	        }
680	        HttpHeaders headers = new HttpHeaders();
681	        Pet pet = petMapper.toPet(petFieldsDto);
682	        owner.setId(ownerId);
683	        pet.setOwner(owner);
684	        pet.getType().setName(null);
685	        this.clinicService.savePet(pet);
686	        PetDto petDto = petMapper.toPetDto(pet);
687	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
688	            .buildAndExpand(pet.getId()).toUri());
689	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
690	    }
691	
692	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
693	    @Override
694	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
695	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
696	        if (currentOwner != null) {
697	            Pet currentPet = this.clinicService.findPetById(petId);
698	            if (currentPet != null) {
699	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
700	                currentPet.setName(petFieldsDto.getName());
701	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
702	                this.clinicService.savePet(currentPet);
703	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
704	            }
705	        }
706	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
707	    }
708	
709	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
710	    @Override
711	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
712	        HttpHeaders headers = new HttpHeaders();
713	        Visit visit = visitMapper.toVisit(visitFieldsDto);
714	        Pet pet = new Pet();
715	        pet.setId(petId);
716	        visit.setPet(pet);
717	        this.clinicService.saveVisit(visit);
718	        VisitDto visitDto = visitMapper.toVisitDto(visit);
719	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
720	            .buildAndExpand(visit.getId()).toUri());
721	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
722	    }
723	
724	
725	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
726	    @Override
727	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
728	        Owner owner = this.clinicService.findOwnerById(ownerId);
729	        if (owner != null) {
730	            Pet pet = owner.getPet(petId);
731	            if (pet != null) {
732	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
